def solve(initial_cells=1e8, volume_ml=1000.0, flow_rate_ml_day=500.0, r_max_day=15.0):
    import math

    # At steady state in a chemostat, the specific growth rate equals
    # the dilution rate D = flow rate / volume.
    dilution_rate = flow_rate_ml_day / volume_ml  # day^-1

    # Doubling time = ln(2) / growth rate
    doubling_time = math.log(2) / dilution_rate  # days

    return {
        "1": {"value": doubling_time, "unit": "day"}
    }

